                  topo.hostname);
  for (auto const& gpu : topo.gpus) {
    SIRIUS_LOG_INFO(
      "  GPU {}: {} (numa={}, pci={})", gpu.id, gpu.name, gpu.numa_node, gpu.pci_bus_id);
  }

  memory_manager_ = std::make_unique<sirius::memory::sirius_memory_reservation_manager>(
    config_.get_memory_space_configs());

